"""Gold labels (from corpus/gold/*.yaml, generated by scripts/build_corpus.py)."""
from __future__ import annotations

import re
from functools import lru_cache

import yaml

from ..config import settings


def _norm_q(q: str) -> str:
    return re.sub(r"\s+", " ", (q or "").strip().lower())


@lru_cache(maxsize=1)
def questions() -> list[dict]:
    p = settings.corpus_dir / "gold" / "questions.yaml"
    if not p.exists():
        return []
    return (yaml.safe_load(p.read_text()) or {}).get("questions", [])


@lru_cache(maxsize=1)
def manifest() -> dict:
    import json
    p = settings.corpus_dir / "gold" / "manifest.json"
    return json.loads(p.read_text()) if p.exists() else {}


def by_question(text: str) -> dict | None:
    n = _norm_q(text)
    return next((q for q in questions() if _norm_q(q["question"]) == n), None)


def by_id(qid: str) -> dict | None:
    return next((q for q in questions() if q["id"] == qid), None)


def reload() -> None:
    questions.cache_clear()
    manifest.cache_clear()
